max_n = 1005

n = int(input())
a = [0] * max_n
b = [0] * max_n
c = [0] * max_n

dp = [[0] * max_n for _ in range(3)]

def result(x, y):
    if x == y + 1 or x == y - 2:
        return 2
    if x == y:
        return 1
    return 0

a[1:] = list(map(int, input().split()))
b[1:] = list(map(int, input().split()))
c[1:] = list(map(int, input().split()))

for k in range(3):
    dp[k][0] = result(k, c[1]) * a[1]

for i in range(2, n + 1):
    for j in range(i - 1, -1, -1):
        for k in range(3):
            curr_score = result(k, c[i]) * a[i]
            dp[k][j] += curr_score
            if j > 0:
                for l in range(3):
                    dp[k][j] = max(dp[k][j], dp[l][j - 1] + curr_score - b[j])

ans = -2e9
x = 0
for j in range(n):
    for k in range(3):
        ans = max(ans, dp[k][j])

print(ans)
